css:
[data-bz-node="ns"] { position: relative; z-index: 3; max-width: 1180px; margin: 0; padding: 80px 40px 40px clamp(40px, 7vw, 120px); }
[data-bz-section="news-stories"] .bz-eyebrow { font-family: var(--font-heading); font-weight: 400; font-size: 13px; letter-spacing: .3em; color: #00cdfd; }
[data-bz-section="news-stories"] [data-bz-node="ns-heading"] { margin-bottom: 34px; }
[data-bz-section="news-stories"] [data-bz-node="ns-heading"] h2 { font-weight: 600; font-size: clamp(36px, 5vw, 64px); line-height: .95; margin: 8px 0 0; }
[data-bz-node="ns-feature"] { position: relative; border-radius: 16px; overflow: hidden; border: 1px solid rgba(255,255,255,.08); min-height: 440px; display: flex; flex-direction: column; justify-content: flex-end; padding: 36px; transition: border-color .3s ease; background: linear-gradient(160deg, #0a5a86 0%, #0a2c46 55%, #240140 100%); }
[data-bz-node="ns-feature"]:hover { border-color: rgba(0,205,253,.4); }
[data-bz-node="ns-feature"]::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(2,6,23,.1) 30%, rgba(2,6,23,.95)); pointer-events: none; }
[data-bz-node="ns-feature"] > * { position: relative; z-index: 2; }
[data-bz-node="ns-feature"] > [data-bz-node="ns-feature-img"], [data-bz-node="ns-feature"] > .bz-block:first-child { position: absolute; inset: 0; z-index: 0; }
[data-bz-node="ns-feature"] > .bz-block:first-child :is(figure, img, .bz-photo) { width: 100%; height: 100%; object-fit: cover; border-radius: 0; margin: 0; }
[data-bz-node="ns-feature-tag"] p { display: inline-block; margin: 0; font-family: var(--font-heading); font-weight: 600; font-size: 11px; letter-spacing: .16em; text-transform: uppercase; color: #020617; background: linear-gradient(135deg, #d705dd, #7a2bd6); padding: 5px 11px; border-radius: 4px; }
[data-bz-node="ns-feature-title"] h3 { font-weight: 600; font-size: clamp(26px, 3vw, 40px); line-height: 1.02; color: #fff; margin: 18px 0 0; }
[data-bz-node="ns-feature-dek"] p { color: #b3c4d3; font-size: 15px; font-weight: 300; line-height: 1.5; margin: 12px 0 0; max-width: 560px; }
[data-bz-node="ns-feature-meta"] p { margin: 14px 0 0; font-size: 12px; letter-spacing: .14em; text-transform: uppercase; color: #6f8498; }
[data-bz-section="news-stories"] .bz-photo--empty { font-size: 0; border: 0; background: transparent; min-height: 100%; }
[data-bz-node^="ns-story-thumb"] .bz-photo--empty { width: 96px; height: 96px; border-radius: 8px; background: repeating-linear-gradient(135deg, rgba(255,255,255,.045) 0 10px, rgba(255,255,255,.015) 10px 20px); }
[data-bz-node="ns-list"] { display: flex; flex-direction: column; gap: 16px; }
[data-bz-node="ns-list"] > .bz-row { padding: 16px; border-radius: 12px; border: 1px solid rgba(255,255,255,.07); background: rgba(6,12,28,.55); transition: transform .28s ease, border-color .28s ease; }
[data-bz-node="ns-list"] > .bz-row:hover { transform: translateX(4px); border-color: rgba(0,205,253,.4); }
[data-bz-node="ns-list"] > .bz-row > .bz-col:first-child { flex: none; }
[data-bz-node^="ns-story-thumb"] { max-width: 96px; }
[data-bz-node^="ns-story-thumb"] img, [data-bz-node^="ns-story-thumb"] .bz-photo { width: 96px; height: 96px; object-fit: cover; border-radius: 8px; }
[data-bz-node^="ns-story-cat"] p { margin: 0; font-family: var(--font-heading); font-size: 11px; letter-spacing: .14em; text-transform: uppercase; color: #d705dd; }
[data-bz-node="ns-list"] > .bz-row:nth-of-type(2) [data-bz-node^="ns-story-cat"] p { color: #00cdfd; }
[data-bz-node="ns-list"] > .bz-row:nth-of-type(3) [data-bz-node^="ns-story-cat"] p { color: #00fbff; }
[data-bz-node^="ns-story-title"] h4 { font-family: var(--font-body); font-weight: 600; font-size: 17px; line-height: 1.2; text-transform: none; color: #eaf2f8; margin: 6px 0 8px; }
[data-bz-node^="ns-story-date"] p { margin: 0; font-size: 12px; letter-spacing: .1em; text-transform: uppercase; color: #6f8498; }
@media (max-width: 640px) { [data-bz-node="ns"] { padding: 60px 20px 30px; } [data-bz-node="ns-feature"] { min-height: 360px; padding: 24px; } }
